/* eslint-disable */
/**
 * #996 — SnapURL uptime canary.
 *
 * Runs every 5 minutes inside AWS CloudWatch Synthetics (the syn-nodejs-
 * puppeteer runtime, which bundles the `Synthetics` and `SyntheticsLogger`
 * globals and a full Node, NOT the 10 KB-capped CloudFront runtime). It does
 * two HTTP checks and FAILS the run — which is what the "redirect canary
 * failed" alarm watches — if either is not exactly right:
 *
 *   1. Redirect path: GET the dedicated canary short link and assert the EXACT
 *      302 and the EXACT Location header. followRedirects is false so the 302
 *      itself is inspected rather than silently chased to the destination —
 *      a link that 200s, 404s, or 302s to the WRONG place all fail here, which
 *      a plain "is it up" check (Route 53 health check, a liveness ping) would
 *      miss. This is the whole reason the issue asked for a canary over a
 *      health check: it verifies the 302 TARGET, not just that something
 *      answers.
 *   2. API health: GET the API health endpoint and assert 200.
 *
 * Configuration comes from environment variables the CDK canary sets, so the
 * one script serves any stage without an edit:
 *   CANARY_REDIRECT_URL   full URL of the canary short link (e.g.
 *                         https://snapurl.in/__canary)
 *   CANARY_EXPECTED_LOCATION  the exact Location the 302 must carry
 *   CANARY_API_HEALTH_URL full URL of the API health endpoint
 *
 * The script is intentionally dependency-free beyond the runtime globals so it
 * stays a single self-contained asset the stack can zip and upload.
 */

const synthetics = require("Synthetics");
const log = require("SyntheticsLogger");

const redirectUrl = process.env.CANARY_REDIRECT_URL;
const expectedLocation = process.env.CANARY_EXPECTED_LOCATION;
const apiHealthUrl = process.env.CANARY_API_HEALTH_URL;

/** Parse a full URL into the { hostname, path, port, protocol } shape the
 *  Synthetics http step wants, without pulling in a URL polyfill. */
function requestOptions(rawUrl) {
  const u = new URL(rawUrl);
  return {
    hostname: u.hostname,
    method: "GET",
    path: u.pathname + u.search,
    port: u.port || (u.protocol === "https:" ? 443 : 80),
    protocol: u.protocol,
    /* The "(monitoring-bot)" token is load-bearing, not decoration: the
       redirect records every click with isBot(userAgent) (packages/domain
       visitor.ts), and the rollup + analytics reader exclude is_bot=true rows
       (rollup.ts, analytics.reader.ts). A UA the bot matcher recognises is
       therefore exactly how the issue's "excluded from user analytics"
       requirement is met — the canary's 288 hits/day never reach a workspace's
       click counts. Keep a bot token ("bot"/"monitor"/"crawler"/...) in here. */
    headers: { "User-Agent": "SnapURL-UptimeCanary/1.0 (monitoring-bot)" },
  };
}

const uptimeCheck = async function () {
  if (!redirectUrl || !expectedLocation || !apiHealthUrl) {
    throw new Error(
      "canary misconfigured: CANARY_REDIRECT_URL, CANARY_EXPECTED_LOCATION and CANARY_API_HEALTH_URL must all be set",
    );
  }

  // ---- Step 1: the redirect 302 and its exact Location target ----
  await synthetics.executeHttpStep(
    "redirect-302-and-location",
    requestOptions(redirectUrl),
    async function (res) {
      return await new Promise((resolve, reject) => {
        if (res.statusCode !== 302) {
          reject(new Error(`redirect returned ${res.statusCode}, expected 302`));
          return;
        }
        const location = res.headers["location"];
        if (location !== expectedLocation) {
          reject(new Error(`redirect Location was "${location}", expected "${expectedLocation}"`));
          return;
        }
        log.info(`redirect OK: 302 -> ${location}`);
        res.on("data", () => {});
        res.on("end", () => resolve());
        res.on("error", (err) => reject(err));
      });
    },
    // Do NOT follow the redirect: we are asserting the 302 itself, not the page
    // it points at.
    { followRedirects: false },
  );

  // ---- Step 2: API health ----
  await synthetics.executeHttpStep(
    "api-health",
    requestOptions(apiHealthUrl),
    async function (res) {
      return await new Promise((resolve, reject) => {
        if (res.statusCode !== 200) {
          reject(new Error(`API health returned ${res.statusCode}, expected 200`));
          return;
        }
        log.info("API health OK: 200");
        res.on("data", () => {});
        res.on("end", () => resolve());
        res.on("error", (err) => reject(err));
      });
    },
  );
};

exports.handler = async () => {
  return await uptimeCheck();
};
